// Process each URL for health checking
const items = [];

for (const item of $input.all()) {
  const urlData = item.json;

  items.push({
    json: {
      url_id: urlData.id,
      url: urlData.url,
      name: urlData.name,
      expected_response: urlData.expected_response,
      timeout: (urlData.timeout_seconds || 30) * 1000,
      failure_threshold: urlData.failure_threshold || 5,
      current_failures: urlData.current_failure_count || 0,
      priority: urlData.priority || 'normal',
      expected_chars: urlData.expected_response_chars || 200,
      http_method: urlData.http_method || 'GET',
      check_start_time: Date.now()
    }
  });
}

return items;

// Process HTTP response and determine health status
const items = [];

for (let i = 0; i < $input.all().length; i++) {
  const inputItem = $input.all()[i];
  const urlData = $('Prepare URL Data').all()[i].json;

  let status = 'error';
  let errorMessage = null;
  let responseTime = null;
  let httpStatusCode = null;
  let responsePreview = null;

  try {
    if (inputItem.json && !inputItem.error) {
      const response = inputItem.json;
      responseTime = Date.now() - urlData.check_start_time;

      httpStatusCode = response.statusCode || response.status || response.code;

      if (response.data && response.data.length > 0) {
        status = 'up';
        httpStatusCode = 200;
        const responseBody = String(response.data || '');
        responsePreview = responseBody.substring(0, urlData.expected_chars);

        if (urlData.expected_response && urlData.expected_response.trim() !== '') {
          if (!responseBody.includes(urlData.expected_response)) {
            status = 'error';
            errorMessage = `Expected response '${urlData.expected_response}' not found`;
          }
        }
      } else if (httpStatusCode && httpStatusCode >= 200 && httpStatusCode < 300) {
        status = 'up';
        const responseBody = String(response.body || response.data || '');
        responsePreview = responseBody.substring(0, urlData.expected_chars);
      } else {
        status = 'down';
        errorMessage = `HTTP ${httpStatusCode || 'unknown'}`;
        responsePreview = (response.body || response.data || '').substring(0, urlData.expected_chars);
      }
    } else {
      status = 'error';
      errorMessage = String(inputItem.error?.message || 'HTTP request failed');
      responseTime = Date.now() - urlData.check_start_time;
    }
  } catch (error) {
    status = 'error';
    errorMessage = String(error.message || 'Unknown processing error');
    responseTime = Date.now() - urlData.check_start_time;
  }

  const newFailureCount = status === 'up' ? 0 : urlData.current_failures + 1;
  const shouldAlert = newFailureCount >= urlData.failure_threshold && status !== 'up' && urlData.current_failures < urlData.failure_threshold;

  items.push({
    json: {
      url_id: urlData.url_id,
      url: urlData.url,
      name: urlData.name,
      status: status,
      response_time_ms: responseTime,
      http_status_code: httpStatusCode,
      response_body_preview: responsePreview ? String(responsePreview) : null,
      error_message: errorMessage,
      current_failures: urlData.current_failures,
      new_failure_count: newFailureCount,
      failure_threshold: urlData.failure_threshold,
      priority: urlData.priority,
      should_alert: shouldAlert,
      checked_at: new Date().toISOString().slice(0, 19).replace('T', ' ')
    }
  });
}

return items;

// Prepare UPDATE query by getting data from Process Response node
const processResponseData = $('Process Response').first().json;

if (!processResponseData.url_id || !processResponseData.status) {
  throw new Error(`Missing required data: url_id=${processResponseData.url_id}, status=${processResponseData.status}`);
}

const sqlQuery = `UPDATE monitored_urls SET last_checked_at = NOW(), last_status = '${processResponseData.status}', current_failure_count = ${processResponseData.new_failure_count || 0}, updated_at = NOW() WHERE id = ${processResponseData.url_id};`;

return {
  json: {
    url_id: processResponseData.url_id,
    url: processResponseData.url,
    name: processResponseData.name,
    status: processResponseData.status,
    new_failure_count: processResponseData.new_failure_count,
    priority: processResponseData.priority,
    should_alert: processResponseData.should_alert,
    error_message: processResponseData.error_message,
    response_time_ms: processResponseData.response_time_ms,
    failure_threshold: processResponseData.failure_threshold,
    sql_query: sqlQuery
  }
};

// Prepare alert recipients query
const alertData = $('Prepare Update Query').first().json;

if (!alertData.url_id || !alertData.status) {
  throw new Error(`Missing required data for alerts: url_id=${alertData.url_id}, status=${alertData.status}`);
}

const sqlQuery = `SELECT agm.notification_type, agm.destination, agm.member_name, ag.group_name, ag.id as group_id FROM url_alert_groups uag JOIN alert_groups ag ON uag.group_id = ag.id JOIN alert_group_members agm ON ag.id = agm.group_id WHERE uag.url_id = ${alertData.url_id} AND uag.is_active = TRUE AND ag.is_active = TRUE AND agm.is_active = TRUE AND (('${alertData.status}' = 'down' AND uag.alert_on_down = TRUE) OR ('${alertData.status}' = 'up' AND uag.alert_on_up = TRUE) OR ('${alertData.status}' = 'timeout' AND uag.alert_on_timeout = TRUE) OR ('${alertData.status}' = 'error' AND uag.alert_on_error = TRUE)) AND NOT EXISTS (SELECT 1 FROM alert_history ah WHERE ah.url_id = uag.url_id AND ah.group_id = ag.id AND ah.notification_type = agm.notification_type AND ah.destination = agm.destination AND ah.sent_at > DATE_SUB(NOW(), INTERVAL 60 MINUTE));`;

return {
  json: {
    ...alertData,
    recipients_sql_query: sqlQuery
  }
};

// Prepare alert messages
const items = [];
const alertData = $('Prepare Recipients Query').first().json;

for (const recipient of $input.all()) {
  const recipientData = recipient.json;
  const recipientName = recipientData.member_name || recipientData.destination;
  const groupName = recipientData.group_name;

  let alertMessage = '';
  let subject = '';

  if (recipientData.notification_type === 'email' || recipientData.notification_type === 'sms') {
    subject = `🚨 ${alertData.priority.toUpperCase()} Alert: ${alertData.name}`;
    alertMessage = `Website Health Alert\n\n🚨 Status: ${alertData.status.toUpperCase()}\n📍 Site: ${alertData.name}\n🔗 URL: ${alertData.url}\n⚠️ Priority: ${alertData.priority.toUpperCase()}\n👥 Group: ${groupName}\n❌ Error: ${alertData.error_message || 'Unknown error'}\n📊 Response Time: ${alertData.response_time_ms || 'N/A'}ms\n🔄 Failures: ${alertData.new_failure_count}/${alertData.failure_threshold}\n🕐 Time: ${new Date().toLocaleString()}`;
  }

  items.push({
    json: {
      ...alertData,
      notification_type: recipientData.notification_type,
      destination: recipientData.destination,
      member_name: recipientName,
      group_name: groupName,
      group_id: recipientData.group_id,
      alert_message: alertMessage,
      alert_subject: subject
    }
  });
}

return items;
